/* @autogenerated */
import { ChangeDetectionStrategy, Component, inject } from '@angular/core';
import { MAT_DIALOG_DATA, MatDialogModule, MatDialogRef } from '@angular/material/dialog';
import { MatButtonModule } from '@angular/material/button';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { TranslocoPipe } from '@jsverse/transloco';
import { OfflineOp } from '@shared/data/offline/offline.model';

export interface OfflineEditDialogData {
  op: OfflineOp;
}

/** Campo de los datos de la operación: los de texto, número o sí/no se pueden cambiar; el resto se muestra. */
interface EditField {
  name: string;
  type: 'text' | 'number' | 'boolean' | 'readonly';
  value: any;
  text: string;
}

/** Corrección a mano de los datos de una operación rechazada (por ejemplo, un error de validación). */
@Component({
  selector: 'offline-edit-dialog',
  standalone: true,
  imports: [MatDialogModule, MatButtonModule, MatFormFieldModule, MatInputModule, MatCheckboxModule, TranslocoPipe],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <h2 mat-dialog-title>{{ 'offline.edit.title' | transloco: { label: data.op.label } }}</h2>
    <mat-dialog-content>
      @if (data.op.error) {
        <p class="error" role="alert">{{ data.op.error.message }}</p>
      }
      <div class="fields">
        @for (field of fields; track field.name) {
          @switch (field.type) {
            @case ('boolean') {
              <mat-checkbox [checked]="field.value" (change)="field.value = $event.checked">
                {{ field.name }}
              </mat-checkbox>
            }
            @case ('readonly') {
              <mat-form-field>
                <mat-label>{{ field.name }}</mat-label>
                <input matInput [value]="field.text" readonly />
              </mat-form-field>
            }
            @default {
              <mat-form-field>
                <mat-label>{{ field.name }}</mat-label>
                <input
                  matInput
                  [type]="field.type"
                  [value]="field.value ?? ''"
                  (input)="field.value = read(field, $any($event.target).value)"
                />
              </mat-form-field>
            }
          }
        }
      </div>
    </mat-dialog-content>
    <mat-dialog-actions align="end">
      <button matButton type="button" mat-dialog-close>{{ 'offline.action.cancel' | transloco }}</button>
      <button matButton="filled" type="button" (click)="save()">{{ 'offline.action.save' | transloco }}</button>
    </mat-dialog-actions>
  `,
  styles: [
    `
      .fields {
        display: grid;
        gap: 4px 16px;
        grid-template-columns: repeat(auto-fill, minmax(14rem, 1fr));
      }
      .error {
        color: var(--mat-sys-error);
        font: var(--mat-sys-body-medium);
      }
    `,
  ],
})
export class OfflineEditDialogComponent {
  readonly data = inject<OfflineEditDialogData>(MAT_DIALOG_DATA);
  private readonly ref = inject(MatDialogRef<OfflineEditDialogComponent, any>);

  readonly fields: EditField[] = Object.entries(this.data.op.payload ?? {})
    .filter(([name]) => !name.startsWith('$'))
    .map(([name, value]) => ({ name, value, type: typeOf(value), text: describe(value) }));

  read(field: EditField, raw: string): any {
    if (field.type !== 'number') {
      return raw;
    }
    return raw === '' ? null : Number(raw);
  }

  save(): void {
    const payload = { ...this.data.op.payload };
    this.fields.filter((field) => field.type !== 'readonly').forEach((field) => (payload[field.name] = field.value));
    this.ref.close(payload);
  }
}

function typeOf(value: any): EditField['type'] {
  if (value === null || value === undefined || typeof value === 'string') {
    return 'text';
  }
  if (typeof value === 'number') {
    return 'number';
  }
  if (typeof value === 'boolean') {
    return 'boolean';
  }
  return 'readonly';
}

function describe(value: any): string {
  if (value instanceof Date) {
    return value.toLocaleString();
  }
  if (value && typeof value === 'object' && '$ref' in value) {
    return String(value.$ref);
  }
  return typeof value === 'object' ? JSON.stringify(value) : String(value ?? '');
}
